test_cases.assertion_pseudocode:
for value in ['direct', 'branch', 'pr']:
    cfg = WorkspaceConfig(merge_strategy=value)
    assert cfg.merge_strategy == value

import ast
for filepath in ['session_lifecycle.py', 'fix_pipeline.py']:
    tree = ast.parse(read_file(filepath))
    for call in find_calls(tree, 'build_pr_body'):
        assert len(call.args) == 0, f'Positional args found in {filepath}'
